<template id="itemTemplate"><div class="item-row border rounded-3 p-3 mb-3"><div class="d-flex justify-content-between align-items-center mb-3"><strong class="item-heading">Item</strong><button class="btn btn-sm btn-light text-danger remove-item" type="button"><i class="bi bi-trash"></i><span class="visually-hidden">Remove item</span></button></div><div class="row g-2"><div class="col-md-6"><label class="form-label">Product type *</label><input class="form-control" data-field="product_type" required placeholder="e.g. Carton box"></div><div class="col-md-6"><label class="form-label">Paper grade / type</label><input class="form-control" data-field="paper_grade" placeholder="Optional"></div><div class="col-4"><label class="form-label">Length</label><input class="form-control" type="number" min="0" step=".01" data-field="length"></div><div class="col-4"><label class="form-label">Width</label><input class="form-control" type="number" min="0" step=".01" data-field="width"></div><div class="col-4"><label class="form-label">Height</label><input class="form-control" type="number" min="0" step=".01" data-field="height"></div><div class="col-4"><label class="form-label">Unit</label><select class="form-select" data-field="unit"><option>mm</option><option>cm</option><option>inch</option></select></div><div class="col-4"><label class="form-label">Quantity *</label><input class="form-control quantity" type="number" min="1" step="1" value="1" data-field="quantity" required></div><div class="col-4"><label class="form-label">Approved unit price *</label><input class="form-control price" type="number" min="0" step=".01" value="0" data-field="unit_price" required></div><div class="col-12"><label class="form-label">Item notes</label><input class="form-control" data-field="notes"></div></div><div class="text-end small mt-2 text-secondary">Line total: <strong class="line-total text-dark">PKR 0.00</strong></div></div></template>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const initialItems=@json($editItems); (()=>{const list=document.getElementById('items');if(!list)return;const template=document.getElementById('itemTemplate');const add=document.getElementById('addItem');const form=document.getElementById('orderForm');const money=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});function refresh(){let total=0;[...list.querySelectorAll('.item-row')].forEach((row,i)=>{row.querySelector('.item-heading').textContent='Item '+(i+1);const q=Number(row.querySelector('[data-field="quantity"]').value||0),p=Number(row.querySelector('[data-field="unit_price"]').value||0),line=q*p;total+=line;row.querySelector('.line-total').textContent=money(line);row.querySelectorAll('[data-field]').forEach(input=>input.name=`items[${i}][${input.dataset.field}]`)});const initial=Number(document.getElementById('initialPayment').value||0);document.getElementById('totalLabel').textContent=money(total);document.getElementById('balanceLabel').textContent=money(Math.max(0,total-initial))}function newItem(){const row=template.content.firstElementChild.cloneNode(true);row.querySelector('.remove-item').addEventListener('click',()=>{row.remove();if(!list.children.length)newItem();refresh()});row.addEventListener('input',refresh);list.appendChild(row);refresh()}add.addEventListener('click',newItem);document.getElementById('initialPayment').addEventListener('input',refresh);form.addEventListener('submit',e=>{const total=[...list.querySelectorAll('.item-row')].reduce((s,r)=>s+Number(r.querySelector('.quantity').value||0)*Number(r.querySelector('.price').value||0),0),initial=Number(document.getElementById('initialPayment').value||0);if(initial>total){e.preventDefault();alert('Initial payment cannot exceed the order total.')} });if(initialItems.length){initialItems.forEach(item=>{newItem();const row=list.lastElementChild;for(const [key,value] of Object.entries(item)){const input=row.querySelector(`[data-field="${key}"]`);if(input&&value!==null)input.value=value}})}else newItem();refresh()})();
</script><script>(()=>{const rows=document.getElementById('allocationRows');if(!rows)return;const tpl=document.getElementById('allocationTemplate');const add=()=>{const row=tpl.content.firstElementChild.cloneNode(true);const n=rows.children.length;row.querySelectorAll('[data-name]').forEach(el=>el.name=`allocations[${n}][${el.dataset.name}]`);row.querySelector('.remove-allocation').addEventListener('click',()=>row.remove());rows.appendChild(row)};document.getElementById('addAllocation').addEventListener('click',add);add()})();</script></body></html>
